import manifest_json from '../../static/assets/manifest.json'
import props_manifest_json from '../../static/assets/props_manifest.json'

/**
 * Typed access to the manifests generated by the external assets repository.
 * The JSON files are imported at build time, so these shapes are checked by the compiler
 * whenever the asset repository exports a new version.
 *
 * File paths in the manifests are relative to the assets folder. Use asset_path() to
 * convert them to a path relative to the static root, which is what the rest of the app uses.
 */

export const ASSETS_FOLDER = 'assets/'

export interface ManifestFile {
  file: string // relative to the assets folder, e.g. 'human/model.glb'
  hash: string
}

export interface ManifestVariation extends ManifestFile {
  name: string // unique per rig, e.g. 'psx-05'
  source: string
}

export interface ManifestAnimation extends ManifestFile {
  name: string // clip name inside the GLB, e.g. 'Walk'
  tags: string[]
  loop: boolean
  root_motion: boolean
  frame_count: number
  duration: number // seconds
  source: string
}

export interface ManifestRig {
  fps: number
  model: ManifestFile
  skeleton: ManifestFile
  variations: ManifestVariation[]
  animations: ManifestAnimation[]
}

export interface AssetManifest {
  version: number
  generated: string
  rigs: Record<string, ManifestRig>
}

export interface ManifestProp extends ManifestFile {
  name: string
  display_name: string
  preview: ManifestFile
  category: string
  tags: string[]
  dimensions: { width: number, depth: number, height: number }
  vertices: number
  triangles: number
  materials: string[]
}

export interface PropsManifest {
  version: number
  generated: string
  categories: string[]
  props: ManifestProp[]
}

export const asset_manifest: AssetManifest = manifest_json
export const props_manifest: PropsManifest = props_manifest_json

/** Convert a manifest file path to a path relative to the static root, e.g. 'assets/human/model.glb' */
export function asset_path (manifest_file: string): string {
  return `${ASSETS_FOLDER}${manifest_file}`
}
